function setView(view){controls.target.set(0,0,0);if(view==='top')camera.position.set(0,83,.01);else if(view==='bottom')camera.position.set(0,-83,.01);else camera.position.set(-38,58,66);const fit=56/(2*Math.tan(THREE.MathUtils.degToRad(camera.fov/2))*camera.aspect);if(camera.position.length()<fit)camera.position.normalize().multiplyScalar(fit);document.querySelector('#view-label').textContent=view==='perspective'?'PERSPECTIVE':(isBeagle?(view==='top'?'FRONT':'BACK'):view.toUpperCase())+' VIEW';document.querySelectorAll('.view-controls button').forEach(b=>b.classList.toggle('active',b.id===view));controls.update();}
